"use client";

import { employeeAPI } from "@/externals/api-service";
import Spinner from "@/components/spinner";
import type { Employee } from "@/model/model";
import Link from "next/link";
import { useEffect, useLayoutEffect, useState } from "react";

const salaryFormatter = new Intl.NumberFormat("en", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

export default function EmployeeListPage() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [revision, setRevision] = useState(0);
  const [error, setError] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<Employee | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [message, setMessage] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    employeeAPI
      .list(controller.signal)
      .then((response) => {
        if (!controller.signal.aborted) {
          setEmployees(response.data);
          setError("");
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setError(
            error instanceof Error ? error.message : "Could not load employees.",
          );
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [revision]);

  useLayoutEffect(() => {
    return () => {
      setLoading(true);
      setDeleteTarget(null);
      setMessage("");
    };
  }, []);

  async function deleteEmployee() {
    if (!deleteTarget || deleting) return;

    setDeleting(true);
    setError("");
    setMessage("");

    try {
      const response = await employeeAPI.delete(deleteTarget.id);
      setEmployees((current) =>
        current.filter((employee) => employee.id !== deleteTarget.id),
      );
      setDeleteTarget(null);
      setMessage(response.message);
    } catch (error) {
      setError(
        error instanceof Error ? error.message : "Could not delete the employee.",
      );
    } finally {
      setDeleting(false);
    }
  }

  return (
    <>
      <div className="page-heading">
        <div>
          <p className="eyebrow">EMPLOYEE DIRECTORY</p>
          <h1>
            Employees{" "}
            {!loading && <span className="count">{employees.length}</span>}
          </h1>
          <p className="muted">View and manage your employee records.</p>
        </div>
        <Link href="/employees/add" className="button button-primary">
          <span aria-hidden>+</span>Add Employee
        </Link>
      </div>
      {message && (
        <p className="notice notice-success" role="status">
          {message}
        </p>
      )}
      {error && (
        <div className="notice notice-error" role="alert">
          <span>{error}</span>
          {!deleteTarget && (
            <button
              className="text-button"
              onClick={() => {
                setError("");
                setLoading(true);
                setRevision((value) => value + 1);
              }}
            >
              Try again
            </button>
          )}
        </div>
      )}

      {deleteTarget && (
        <div className="notice delete-confirmation" role="alert">
          <div>
            <strong>Delete {deleteTarget.name}?</strong>
            <p>This will permanently remove this employee.</p>
          </div>
          <div className="actions">
            <button
              className="button button-secondary"
              disabled={deleting}
              onClick={() => setDeleteTarget(null)}
            >
              Cancel
            </button>

            <button
              className="button button-danger"
              disabled={deleting}
              aria-busy={deleting}
              onClick={deleteEmployee}
            >
              {deleting && <Spinner />}
              {deleting ? "Deleting..." : "Delete employee"}
            </button>
          </div>
        </div>
      )}

      <section className="card" aria-label="Employee list" aria-busy={loading}>
        {loading ? (
          <div className="empty-state loading-state" role="status">
            <Spinner size="large" />
            <span>Loading employees...</span>
          </div>
        ) : employees.length === 0 && !error ? (
          <div className="empty-state">
            <span className="empty-icon" aria-hidden="true">
              E
            </span>
            <h2>No employees yet</h2>
            <p className="muted">Add your first employee to get started.</p>
            <Link href="/employees/add" className="button button-primary">
              Add Employee
            </Link>
          </div>
        ) : employees.length > 0 ? (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">ID</th>
                  <th scope="col">Employee</th>
                  <th scope="col">Department</th>
                  <th scope="col" className="number">
                    Salary
                  </th>
                  <th scope="col" className="actions-heading">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {employees.map((employee) => {
                  const path = `/employees/${encodeURIComponent(String(employee.id))}`;
                  return (
                    <tr key={employee.id}>
                      <td className="employee-id">{employee.id}</td>
                      <th scope="row">
                        {/* <div className="employee-cell">
                          <EmployeeAvatar name={employee.name} />
                          <span>{employee.name}</span>
                        </div> */}
                      </th>
                      <td>
                        <span className="department">
                          {employee.department}
                        </span>
                      </td>
                      <td className="number">
                        {salaryFormatter.format(employee.salary)}
                      </td>
                      <td>
                        <div className="row-actions">
                          <Link
                            href={path}
                            aria-label={`View ${employee.name}`}
                          >
                            View
                          </Link>
                          <Link
                            href={`${path}/edit`}
                            aria-label={`Edit ${employee.name}`}
                          >
                            Edit
                          </Link>
                          <button
                            className="text-button danger-text"
                            aria-label={`Delete ${employee.name}`}
                            disabled={deleting}
                            onClick={() => {
                              setDeleteTarget(employee);
                              setMessage("");
                              setError("");
                            }}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <div className="table-footer">
              {employees.length} employee{employees.length === 1 ? "" : "s"}
            </div>
          </div>
        ) : null}
      </section>
    </>
  );
}
